SourceCode.Declaration:
/// <summary>
/// A device setup request, sent by the token service on behalf of a new device: the setup code
/// from the QR code, the device and its public key. getDeviceKey uses DeviceId only.
/// </summary>
[DataContractAttribute]
class HSMobileOpsDeviceSetupRequest
{
    str        code;
    str        deviceId;
    str        publicKey;
    str        deviceBrand;
    str        deviceModel;
    str        platform;
    str        platformVersion;
    str        appVersionName;
}

Method.Source:
[DataMemberAttribute('Code')]
public str parmCode(str _value = code)
{
    code = _value;
    return code;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('PublicKey')]
public str parmPublicKey(str _value = publicKey)
{
    publicKey = _value;
    return publicKey;
}

[DataMemberAttribute('DeviceBrand')]
public str parmDeviceBrand(str _value = deviceBrand)
{
    deviceBrand = _value;
    return deviceBrand;
}

[DataMemberAttribute('DeviceModel')]
public str parmDeviceModel(str _value = deviceModel)
{
    deviceModel = _value;
    return deviceModel;
}

[DataMemberAttribute('Platform')]
public str parmPlatform(str _value = platform)
{
    platform = _value;
    return platform;
}

[DataMemberAttribute('PlatformVersion')]
public str parmPlatformVersion(str _value = platformVersion)
{
    platformVersion = _value;
    return platformVersion;
}

[DataMemberAttribute('AppVersionName')]
public str parmAppVersionName(str _value = appVersionName)
{
    appVersionName = _value;
    return appVersionName;
}
